7	import React, { useState, useEffect } from 'react';
8	import { Box, Text } from 'ink';
9	import { ToolCallStatus, mapCoreStatusToDisplayStatus } from '../../types.js';
10	import { GeminiRespondingSpinner } from '../GeminiRespondingSpinner.js';
11	import {
12	  SHELL_COMMAND_NAME,
13	  SHELL_NAME,
14	  TOOL_STATUS,
15	  SHELL_FOCUS_HINT_DELAY_MS,
16	} from '../../constants.js';
17	import { theme } from '../../semantic-colors.js';
18	import {
19	  type Config,
20	  SHELL_TOOL_NAME,
21	  isCompletedAskUserTool,
22	  type ToolResultDisplay,
23	  CoreToolCallStatus,
24	} from '@google/gemini-cli-core';
25	import { useInactivityTimer } from '../../hooks/useInactivityTimer.js';
26	import { formatCommand } from '../../utils/keybindingUtils.js';
27	import { Command } from '../../../config/keyBindings.js';
28	
29	export const STATUS_INDICATOR_WIDTH = 3;
30	
31	/**
32	 * Returns true if the tool name corresponds to a shell tool.
33	 */
34	export function isShellTool(name: string): boolean {
35	  return (
36	    name === SHELL_COMMAND_NAME ||
37	    name === SHELL_NAME ||
38	    name === SHELL_TOOL_NAME
39	  );
40	}
41	
42	/**
43	 * Returns true if the shell tool call is currently focusable.
44	 */
45	export function isThisShellFocusable(
46	  name: string,
47	  status: CoreToolCallStatus,
48	  config?: Config,
49	): boolean {
50	  return !!(
51	    isShellTool(name) &&
52	    status === CoreToolCallStatus.Executing &&
53	    config?.getEnableInteractiveShell()
54	  );
55	}
56	
57	/**
58	 * Returns true if this specific shell tool call is currently focused.
59	 */
60	export function isThisShellFocused(
61	  name: string,
62	  status: CoreToolCallStatus,
63	  ptyId?: number,
64	  activeShellPtyId?: number | null,
65	  embeddedShellFocused?: boolean,
66	): boolean {
67	  return !!(
68	    isShellTool(name) &&
69	    status === CoreToolCallStatus.Executing &&
70	    ptyId === activeShellPtyId &&
71	    embeddedShellFocused
72	  );
73	}
74	
75	/**
76	 * Hook to manage focus hint state.
77	 */
78	export function useFocusHint(
79	  isThisShellFocusable: boolean,
80	  isThisShellFocused: boolean,
81	  resultDisplay: ToolResultDisplay | undefined,
82	) {
83	  const [userHasFocused, setUserHasFocused] = useState(false);
84	
85	  // Derive a stable reset key for the inactivity timer. For strings and arrays
86	  // (shell output), we use the length to capture updates without referential
87	  // identity issues or expensive deep comparisons.
88	  const resetKey =
89	    typeof resultDisplay === 'string'
90	      ? resultDisplay.length
91	      : Array.isArray(resultDisplay)
92	        ? resultDisplay.length
93	        : !!resultDisplay;
94	
95	  const showFocusHint = useInactivityTimer(
96	    isThisShellFocusable,
97	    resetKey,
98	    SHELL_FOCUS_HINT_DELAY_MS,
99	  );
100	
101	  useEffect(() => {
102	    if (isThisShellFocused) {
103	      setUserHasFocused(true);
104	    }
105	  }, [isThisShellFocused]);
106	
107	  const shouldShowFocusHint =
108	    isThisShellFocusable && (showFocusHint || userHasFocused);
109	
110	  return { shouldShowFocusHint };
111	}
112	
113	/**
114	 * Component to render the focus hint.
115	 */
116	export const FocusHint: React.FC<{
117	  shouldShowFocusHint: boolean;
118	  isThisShellFocused: boolean;
119	}> = ({ shouldShowFocusHint, isThisShellFocused }) => {
120	  if (!shouldShowFocusHint) {
121	    return null;
122	  }
123	
124	  return (
125	    <Box marginLeft={1} flexShrink={0}>
126	      <Text color={theme.text.accent}>
127	        {isThisShellFocused
128	          ? `(${formatCommand(Command.UNFOCUS_SHELL_INPUT)} to unfocus)`
129	          : `(${formatCommand(Command.FOCUS_SHELL_INPUT)} to focus)`}
130	      </Text>
131	    </Box>
132	  );
133	};
134	
135	export type TextEmphasis = 'high' | 'medium' | 'low';
136	
137	type ToolStatusIndicatorProps = {
138	  status: CoreToolCallStatus;
139	  name: string;
140	};
141	
142	export const ToolStatusIndicator: React.FC<ToolStatusIndicatorProps> = ({
143	  status: coreStatus,
144	  name,
145	}) => {
146	  const status = mapCoreStatusToDisplayStatus(coreStatus);
147	  const isShell = isShellTool(name);
148	  const statusColor = isShell ? theme.ui.symbol : theme.status.warning;
149	
150	  return (
151	    <Box minWidth={STATUS_INDICATOR_WIDTH}>
152	      {status === ToolCallStatus.Pending && (
153	        <Text color={theme.status.success}>{TOOL_STATUS.PENDING}</Text>
154	      )}
155	      {status === ToolCallStatus.Executing && (
156	        <GeminiRespondingSpinner
157	          spinnerType="toggle"
158	          nonRespondingDisplay={TOOL_STATUS.EXECUTING}
159	        />
160	      )}
161	      {status === ToolCallStatus.Success && (
162	        <Text color={theme.status.success} aria-label={'Success:'}>
163	          {TOOL_STATUS.SUCCESS}
164	        </Text>
165	      )}
166	      {status === ToolCallStatus.Confirming && (
167	        <Text color={statusColor} aria-label={'Confirming:'}>
168	          {TOOL_STATUS.CONFIRMING}
169	        </Text>
170	      )}
171	      {status === ToolCallStatus.Canceled && (
172	        <Text color={statusColor} aria-label={'Canceled:'} bold>
173	          {TOOL_STATUS.CANCELED}
174	        </Text>
175	      )}
176	      {status === ToolCallStatus.Error && (
177	        <Text color={theme.status.error} aria-label={'Error:'} bold>
178	          {TOOL_STATUS.ERROR}
179	        </Text>
180	      )}
181	    </Box>
182	  );
183	};
184	
185	type ToolInfoProps = {
186	  name: string;
187	  description: string;
188	  status: CoreToolCallStatus;
189	  emphasis: TextEmphasis;
190	  progressMessage?: string;
191	  progressPercent?: number;
192	  originalRequestName?: string;
193	};
194	
195	export const ToolInfo: React.FC<ToolInfoProps> = ({
196	  name,
197	  description,
198	  status: coreStatus,
199	  emphasis,
200	  progressMessage,
201	  progressPercent,
202	  originalRequestName,
203	}) => {
204	  const status = mapCoreStatusToDisplayStatus(coreStatus);
205	  const nameColor = React.useMemo<string>(() => {
206	    switch (emphasis) {
207	      case 'high':
208	        return theme.text.primary;
209	      case 'medium':
210	        return theme.text.primary;
211	      case 'low':
212	        return theme.text.secondary;
213	      default: {
214	        const exhaustiveCheck: never = emphasis;
215	        return exhaustiveCheck;
216	      }
217	    }
218	  }, [emphasis]);
219	
220	  // Hide description for completed Ask User tools (the result display speaks for itself)
221	  const isCompletedAskUser = isCompletedAskUserTool(name, status);
222	
223	  let displayDescription = description;
224	  if (status === ToolCallStatus.Executing) {
225	    const parts: string[] = [];
226	    if (progressMessage) {
227	      parts.push(progressMessage);
228	    }
229	    if (progressPercent !== undefined) {
230	      parts.push(`${Math.round(progressPercent)}%`);
231	    }
232	
233	    if (parts.length > 0) {
234	      const progressInfo = parts.join(' - ');
235	      displayDescription = description
236	        ? `${description} (${progressInfo})`
237	        : progressInfo;
238	    }
239	  }
240	
241	  return (
242	    <Box overflow="hidden" height={1} flexGrow={1} flexShrink={1}>
243	      <Text strikethrough={status === ToolCallStatus.Canceled} wrap="truncate">
244	        <Text color={nameColor} bold>
245	          {name}
246	        </Text>
247	        {originalRequestName && originalRequestName !== name && (
248	          <Text color={theme.text.secondary} italic>
249	            {' '}
250	            (redirection from {originalRequestName})
251	          </Text>
252	        )}
253	        {!isCompletedAskUser && (
254	          <>
255	            {' '}
256	            <Text color={theme.text.secondary}>{displayDescription}</Text>
257	          </>
258	        )}
259	      </Text>
260	    </Box>
261	  );
262	};
