28	export interface ToolMessageProps extends IndividualToolCallDisplay {
29	  availableTerminalHeight?: number;
30	  terminalWidth: number;
31	  emphasis?: TextEmphasis;
32	  renderOutputAsMarkdown?: boolean;
33	  isFirst: boolean;
34	  borderColor: string;
35	  borderDimColor: boolean;
36	  activeShellPtyId?: number | null;
37	  embeddedShellFocused?: boolean;
38	  ptyId?: number;
39	  config?: Config;
40	}
41	
42	export const ToolMessage: React.FC<ToolMessageProps> = ({
43	  name,
44	  description,
45	  resultDisplay,
46	  status,
47	  availableTerminalHeight,
48	  terminalWidth,
49	  emphasis = 'medium',
50	  renderOutputAsMarkdown = true,
51	  isFirst,
52	  borderColor,
53	  borderDimColor,
54	  activeShellPtyId,
55	  embeddedShellFocused,
56	  ptyId,
57	  config,
58	  progressMessage,
59	  progressPercent,
60	  originalRequestName,
61	}) => {
62	  const isThisShellFocused = checkIsShellFocused(
63	    name,
64	    status,
65	    ptyId,
66	    activeShellPtyId,
67	    embeddedShellFocused,
68	  );
69	
70	  const isThisShellFocusable = checkIsShellFocusable(name, status, config);
71	
72	  const { shouldShowFocusHint } = useFocusHint(
73	    isThisShellFocusable,
74	    isThisShellFocused,
75	    resultDisplay,
76	  );
77	
78	  return (
79	    // It is crucial we don't replace this <> with a Box because otherwise the
80	    // sticky header inside it would be sticky to that box rather than to the
81	    // parent component of this ToolMessage.
82	    <>
83	      <StickyHeader
84	        width={terminalWidth}
85	        isFirst={isFirst}
86	        borderColor={borderColor}
87	        borderDimColor={borderDimColor}
88	      >
89	        <ToolStatusIndicator status={status} name={name} />
90	        <ToolInfo
91	          name={name}
92	          status={status}
93	          description={description}
94	          emphasis={emphasis}
95	          progressMessage={progressMessage}
96	          progressPercent={progressPercent}
97	          originalRequestName={originalRequestName}
98	        />
99	        <FocusHint
100	          shouldShowFocusHint={shouldShowFocusHint}
101	          isThisShellFocused={isThisShellFocused}
102	        />
103	        {emphasis === 'high' && <TrailingIndicator />}
104	      </StickyHeader>
105	      <Box
106	        width={terminalWidth}
107	        borderStyle="round"
108	        borderColor={borderColor}
109	        borderDimColor={borderDimColor}
110	        borderTop={false}
111	        borderBottom={false}
112	        borderLeft={true}
113	        borderRight={true}
114	        paddingX={1}
115	        flexDirection="column"
116	      >
117	        <ToolResultDisplay
118	          resultDisplay={resultDisplay}
119	          availableTerminalHeight={availableTerminalHeight}
120	          terminalWidth={terminalWidth}
121	          renderOutputAsMarkdown={renderOutputAsMarkdown}
122	          hasFocus={isThisShellFocused}
123	        />
124	        {isThisShellFocused && config && (
125	          <Box paddingLeft={STATUS_INDICATOR_WIDTH} marginTop={1}>
126	            <ShellInputPrompt
127	              activeShellPtyId={activeShellPtyId ?? null}
128	              focus={embeddedShellFocused}
129	            />
130	          </Box>
131	        )}
132	      </Box>
133	    </>
134	  );
135	};
