7	import {
8	  type ToolCall,
9	  type SerializableConfirmationDetails,
10	  type ToolResultDisplay,
11	  debugLogger,
12	  CoreToolCallStatus,
13	} from '@google/gemini-cli-core';
14	import {
15	  type HistoryItemToolGroup,
16	  type IndividualToolCallDisplay,
17	} from '../types.js';
18	
19	/**
20	 * Transforms `ToolCall` objects into `HistoryItemToolGroup` objects for UI
21	 * display. This is a pure projection layer and does not track interaction
22	 * state.
23	 */
24	export function mapToDisplay(
25	  toolOrTools: ToolCall[] | ToolCall,
26	  options: {
27	    borderTop?: boolean;
28	    borderBottom?: boolean;
29	    borderColor?: string;
30	    borderDimColor?: boolean;
31	  } = {},
32	): HistoryItemToolGroup {
33	  const toolCalls = Array.isArray(toolOrTools) ? toolOrTools : [toolOrTools];
34	  const { borderTop, borderBottom, borderColor, borderDimColor } = options;
35	
36	  const toolDisplays = toolCalls.map((call): IndividualToolCallDisplay => {
37	    let description: string;
38	    let renderOutputAsMarkdown = false;
39	
40	    const displayName = call.tool?.displayName ?? call.request.name;
41	
42	    if (call.status === CoreToolCallStatus.Error) {
43	      description = JSON.stringify(call.request.args);
44	    } else {
45	      description = call.invocation.getDescription();
46	      renderOutputAsMarkdown = call.tool.isOutputMarkdown;
47	    }
48	
49	    const baseDisplayProperties = {
50	      callId: call.request.callId,
51	      name: displayName,
52	      description,
53	      renderOutputAsMarkdown,
54	    };
55	
56	    let resultDisplay: ToolResultDisplay | undefined = undefined;
57	    let confirmationDetails: SerializableConfirmationDetails | undefined =
58	      undefined;
59	    let outputFile: string | undefined = undefined;
60	    let ptyId: number | undefined = undefined;
61	    let correlationId: string | undefined = undefined;
62	    let progressMessage: string | undefined = undefined;
63	    let progressPercent: number | undefined = undefined;
64	
65	    switch (call.status) {
66	      case CoreToolCallStatus.Success:
67	        resultDisplay = call.response.resultDisplay;
68	        outputFile = call.response.outputFile;
69	        break;
70	      case CoreToolCallStatus.Error:
71	      case CoreToolCallStatus.Cancelled:
72	        resultDisplay = call.response.resultDisplay;
73	        break;
74	      case CoreToolCallStatus.AwaitingApproval:
75	        correlationId = call.correlationId;
76	        // Pass through details. Context handles dispatch (callback vs bus).
77	        confirmationDetails = call.confirmationDetails;
78	        break;
79	      case CoreToolCallStatus.Executing:
80	        resultDisplay = call.liveOutput;
81	        ptyId = call.pid;
82	        progressMessage = call.progressMessage;
83	        progressPercent = call.progressPercent;
84	        break;
85	      case CoreToolCallStatus.Scheduled:
86	      case CoreToolCallStatus.Validating:
87	        break;
88	      default: {
89	        const exhaustiveCheck: never = call;
90	        debugLogger.warn(
91	          `Unhandled tool call status in mapper: ${
92	            (exhaustiveCheck as ToolCall).status
93	          }`,
94	        );
95	        break;
96	      }
97	    }
98	
99	    return {
100	      ...baseDisplayProperties,
101	      status: call.status,
102	      resultDisplay,
103	      confirmationDetails,
104	      outputFile,
105	      ptyId,
106	      correlationId,
107	      progressMessage,
108	      progressPercent,
109	      approvalMode: call.approvalMode,
110	      originalRequestName: call.request.originalRequestName,
111	    };
112	  });
113	
114	  return {
115	    type: 'tool_group',
116	    tools: toolDisplays,
117	    borderTop,
118	    borderBottom,
119	    borderColor,
120	    borderDimColor,
121	  };
122	}
