20	export const ROOT_SCHEDULER_ID = 'root';
21	
22	/**
23	 * Internal core statuses for the tool call state machine.
24	 */
25	export enum CoreToolCallStatus {
26	  Validating = 'validating',
27	  Scheduled = 'scheduled',
