type McpProgressIndicatorProps = {
  progress: number;
  total?: number;
  message?: string;
  barWidth: number;
};

/**
 * Renders a visual progress bar for MCP tool calls.
 *
 * Supports both determinate mode (a valid `total` is provided, rendering a
 * filled bar and a percentage) and indeterminate mode (no valid `total`,
 * rendering an empty bar and the raw `progress` value).
 */
export const McpProgressIndicator: React.FC<McpProgressIndicatorProps> = ({
  progress,
  total,
  message,
  barWidth,
}) => {
  const width = Math.max(0, Math.floor(barWidth));

  // A total is only usable if it is a positive, finite number.
  const hasValidTotal =
    typeof total === 'number' &&
    Number.isFinite(total) &&
    total > 0 &&
    !Number.isNaN(total);

  let filled = 0;
  let label: string;
  if (hasValidTotal) {
    const ratio = Math.min(1, Math.max(0, progress / total));
    filled = Math.round(ratio * width);
    label = `${Math.round(ratio * 100)}%`;
  } else {
    // Indeterminate mode: we cannot compute a fraction, so show the raw value.
    label = `${progress}`;
  }

  const empty = Math.max(0, width - filled);
  const bar =
    PROGRESS_BAR_FILLED_CHAR.repeat(filled) +
    PROGRESS_BAR_EMPTY_CHAR.repeat(empty);

  return (
    <Box flexDirection="row">
      <Text color={theme.text.accent}>{bar}</Text>
      <Text color={theme.text.secondary}>
        {' '}
        {label}
        {message ? ` ${message}` : ''}
      </Text>
    </Box>
  );
};

